fn greater_equal(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Using iterator zip to pair elements and map to compare
    a.iter()
        .zip(b.iter())
        .map(|(x, y)| x >= y)
        .collect()
}